CREATE SEQUENCE record_effects START 10;
CREATE FUNCTION record_pair(value bigint,OUT first_value bigint,OUT second_value bigint) LANGUAGE sql VOLATILE AS 'SELECT $1,$1';
CREATE FUNCTION record_pair(value text,OUT first_value text,OUT second_value text) RETURNS SETOF record LANGUAGE sql VOLATILE AS 'SELECT $1,$1';
CREATE FUNCTION record_pair(value integer,OUT first_value integer,OUT second_value integer) RETURNS SETOF record LANGUAGE sql VOLATILE AS 'SELECT $1,$1';
CREATE FUNCTION record_set(value bigint,OUT first_value bigint,OUT second_value bigint) RETURNS SETOF record LANGUAGE sql VOLATILE AS 'SELECT $1,$1 UNION ALL SELECT $1+1,$1+1';
CREATE TABLE record_inputs(id integer);
INSERT INTO record_inputs VALUES (1),(2);
SELECT (record_pair(nextval('record_effects'))).*;
SELECT last_value FROM record_effects;
SELECT (record_pair((SELECT nextval('record_effects')))).*;
SELECT last_value FROM record_effects;
SELECT id,(record_pair(nextval('record_effects'))).* FROM record_inputs ORDER BY id;
SELECT last_value FROM record_effects;
SELECT * FROM (SELECT (record_pair(nextval('record_effects'))).*) AS nested;
SELECT (record_pair('set'::text)).*;
SELECT (record_pair('untyped')).*;
SELECT pg_typeof((record_pair(9)).first_value);
SELECT (record_set(nextval('record_effects'))).*;
SELECT last_value FROM record_effects;
SELECT record_set(nextval('record_effects')),record_set(nextval('record_effects'));
SELECT last_value FROM record_effects;
SELECT record_set(nextval('record_effects')),record_set(nextval('record_effects')+0);
SELECT last_value FROM record_effects;
SELECT (record_pair(generate_series(nextval('record_effects'),nextval('record_effects')+1))).*;
SELECT last_value FROM record_effects;
INSERT INTO record_inputs VALUES (3) RETURNING (record_pair(nextval('record_effects'))).*;
UPDATE record_inputs SET id=id WHERE id=3 RETURNING (record_pair(nextval('record_effects'))).*;
DELETE FROM record_inputs WHERE id=3 RETURNING (record_pair(nextval('record_effects'))).*;
CREATE TABLE record_merge_source(id integer);
INSERT INTO record_merge_source VALUES (4);
MERGE INTO record_inputs AS target USING record_merge_source AS source ON target.id=source.id WHEN NOT MATCHED THEN INSERT VALUES(source.id) RETURNING (record_pair(nextval('record_effects'))).*;
SELECT last_value FROM record_effects;
SELECT (information_schema._pg_expandarray(ARRAY['a',NULL,'c'])).*;
SELECT (result.keys).x,(result.keys).n FROM (SELECT information_schema._pg_expandarray(ARRAY['x',NULL,'z']) AS keys) AS result ORDER BY (result.keys).n;
CREATE FUNCTION record_named_set(value integer,marker text DEFAULT 'default',OUT first_value integer,OUT second_value text) RETURNS SETOF record LANGUAGE sql VOLATILE AS 'SELECT $1,$2';
CREATE FUNCTION record_variadic_set(VARIADIC values_in integer[]) RETURNS TABLE(value integer,marker integer) LANGUAGE sql VOLATILE AS 'SELECT unnest($1),7';
SELECT (record_named_set(marker=>'named',value=>7)).*;
SELECT (record_named_set(value=>8)).*;
SELECT (record_variadic_set(VARIADIC ARRAY[4,5])).*;
DROP FUNCTION record_named_set(integer,text);
DROP FUNCTION record_variadic_set(integer[]);
DROP TABLE record_merge_source;
DROP TABLE record_inputs;
DROP FUNCTION record_pair(bigint);
DROP FUNCTION record_pair(text);
DROP FUNCTION record_pair(integer);
DROP FUNCTION record_set(bigint);
DROP SEQUENCE record_effects;
